#!/usr/bin/env python3
"""Browser end-to-end tests (Playwright + Chrome). Usage: python3 tests/e2e/run.py [t_name ...]
Needs: pip install playwright, and Chrome (override the path with CHROME_PATH, default /usr/bin/google-chrome).
Starts its own local HTTP server (the service worker needs http); no network needed."""
import asyncio, functools, http.server, json, os, socketserver, sys, threading
from playwright.async_api import async_playwright

ROOT = os.path.abspath(os.path.join(os.path.dirname(__file__), '..', '..'))
CHROME = os.environ.get('CHROME_PATH', '/usr/bin/google-chrome')

class Quiet(http.server.SimpleHTTPRequestHandler):
    def log_message(self, *a): pass
srv = socketserver.TCPServer(('127.0.0.1', 0), functools.partial(Quiet, directory=ROOT))
URL = 'http://127.0.0.1:%d/index.html' % srv.server_address[1]
threading.Thread(target=srv.serve_forever, daemon=True).start()

VERSION = json.load(open(os.path.join(ROOT, 'package.json')))['version']
results, page_errors = [], []
def check(name, cond, detail=''):
    results.append((name, bool(cond))); print(('  ok  ' if cond else 'FAIL  ') + name + ('' if cond else '   ' + str(detail)))

async def new_page(browser, **ctx):
    c = await browser.new_context(**ctx); pg = await c.new_page()
    pg.on('pageerror', lambda e: page_errors.append(str(e)))
    return c, pg
async def enter(pg):                                   # the app opens on the title screen: tap Enter
    if await pg.evaluate("()=>window.__flow&&__flow.state==='title'"): await pg.click('[data-act="enter"]')
async def fresh(pg, query=''):
    await pg.goto(URL + query); await pg.evaluate('()=>localStorage.clear()'); await pg.reload(); await pg.wait_for_timeout(400); await enter(pg); await enter(pg)
flow = lambda pg: pg.evaluate('()=>__flow.state')
async def start_run(pg, mode='classic'):               # menu → prep screen (team + gear) → Start
    await pg.click('[data-act="prep:%s"]' % mode); await pg.click('#ov [data-act="start"]')
async def open_level(pg, i):                           # level list → (chapter opening card, once) → briefing
    await pg.click('[data-act="level:%d"]' % i)
    if await flow(pg) == 'story': await pg.click('[data-act="storygo"]')
save = lambda pg: pg.evaluate("()=>JSON.parse(localStorage.getItem('slidingcups.save'))")
async def swipe(pg, dx=0):
    h = await pg.evaluate("()=>{const c=__game.held;if(!c)return null;const p=__project(c.x,c.y);const r=document.getElementById('c').getBoundingClientRect();return {x:p.sx+r.left,y:p.sy+r.top-8}}")
    if not h: return False
    await pg.mouse.move(h['x'], h['y']); await pg.mouse.down()
    for i in range(1, 6): await pg.mouse.move(h['x'] + dx, h['y'] - i * 50)
    await pg.mouse.up(); return True
async def force_loss(pg):
    await pg.evaluate("()=>{const g=__game;g.world.cups.push(SC.Physics.makeCup(g.world,0,2,100,800))}")
    await pg.wait_for_timeout(4300)
async def clear_level(pg):
    await pg.evaluate("()=>{const g=__game,P=SC.Physics,k=g.mode.goalKinds(g);for(const kind of k){g.world.cups.push(P.makeCup(g.world,kind,4,150,300),P.makeCup(g.world,kind,4,250,300));}g.phase='flying'}")
    await pg.wait_for_timeout(1500)

async def t_menu_flow(b):
    print('Menus and screen flow'); c, pg = await new_page(b, viewport={'width': 820, 'height': 1100}); await fresh(pg)
    check('opens on the menu', await flow(pg) == 'menu')
    await pg.click('[data-act="prep:classic"]'); check('Classic → prep screen (Prepare for battle)', await flow(pg) == 'prep' and 'Prepare for battle' in await pg.inner_text('#ov'))
    await pg.click('#ov [data-act="start"]'); check('Start → playing', await flow(pg) == 'playing')
    await pg.click('#bPause'); check('pause → paused', await flow(pg) == 'paused')
    await pg.click('[data-act="resume"]'); check('resume → playing', await flow(pg) == 'playing')
    await force_loss(pg); await pg.wait_for_timeout(1300)
    check('cup resting inside the line too long → result screen', await flow(pg) == 'result' and await pg.evaluate("()=>__game.phase") == 'over')
    await pg.click('[data-act="restart"]'); check('play again skips the prep screen → playing, phase=ready', await flow(pg) == 'playing' and await pg.evaluate("()=>__game.phase") == 'ready')
    await pg.click('#bPause'); await pg.click('[data-act="menu"]'); check('back to menu', await flow(pg) == 'menu')
    await pg.click('[data-act="prep:practice"]'); check('Proving Grounds → prep screen too', await flow(pg) == 'prep' and 'Proving Grounds' in await pg.inner_text('#ov'))
    await pg.click('#ov [data-act="menu"]'); check('prep Back → menu', await flow(pg) == 'menu')
    await start_run(pg, 'practice'); check('Practice mode', await pg.evaluate("()=>__game.mode.id") == 'practice')
    await pg.wait_for_timeout(800)
    check('dragon sprites (with expressions) loaded', await pg.evaluate("()=>['dragon_t1','dragon_t6','dragon_t3_happy','dragon_t4_fast','dragon_t2_blink'].every(k=>__sprites.imgs[k]&&__sprites.imgs[k].ok)"))
    await c.close()

async def t_play_sound(b):
    print('Launch and sound'); c, pg = await new_page(b, viewport={'width': 820, 'height': 1100}); await fresh(pg)
    await start_run(pg, 'practice')
    for i in range(4): await swipe(pg, (i % 3 - 1) * 20); await pg.wait_for_timeout(2300)
    st = await pg.evaluate('()=>__sfx.stats')
    check('launch, spawn and wall hits trigger sounds', st.get('launch', 0) >= 3 and st.get('spawn', 0) >= 3 and st.get('wall', 0) >= 1, st)
    await pg.click('#bSound'); before = json.dumps(await pg.evaluate('()=>__sfx.stats'))
    await pg.click('#bPause'); await pg.click('[data-act="resume"]')
    check('no sounds after muting', json.dumps(await pg.evaluate('()=>__sfx.stats')) == before)
    check('sound setting is saved', (await save(pg))['sound'] is False)
    # iOS can refuse new canvases when canvas memory runs out (getContext → null): the held cup must still be drawn, with no error bar
    await pg.evaluate("()=>{const gc=HTMLCanvasElement.prototype.getContext;HTMLCanvasElement.prototype.getContext=function(t,o){return this.id==='c'?gc.call(this,t,o):null};for(const c of __sprites.cache.values())c.cv.width=0;__sprites.cache.clear()}")
    await pg.wait_for_timeout(400)
    px = await pg.evaluate("()=>{const c=__game.held;if(!c)return null;const p=__project(c.x,c.y),cv=document.getElementById('c'),k=cv.width/cv.getBoundingClientRect().width,R=c.r*p.s;const g=cv.getContext('2d');let n=0;for(let i=0;i<20;i++){const d=g.getImageData(Math.round(p.sx*k),Math.round((p.sy-R*2*i/20)*k),1,1).data;if(Math.abs(d[0]-242)+Math.abs(d[1]-220)+Math.abs(d[2]-170)>80)n++}return n}")
    check('held cup still drawn when sprite copies cannot be made; no error bar', px is not None and px >= 6 and not await pg.evaluate("()=>document.getElementById('err').textContent"), px)
    await c.close()

async def t_progress(b):
    print('VP, unlocks and saves'); c, pg = await new_page(b, viewport={'width': 820, 'height': 1100}); await fresh(pg)
    await start_run(pg)
    await pg.evaluate('()=>{__game.score=5300;__game.kings=1}'); await force_loss(pg); await pg.wait_for_timeout(1300)
    check('VP banked after losing (5300 points + 1 king = 20 VP) plus best score', (await save(pg))['vp'] == 20 and (await save(pg))['best']['classic'] == 5300, await save(pg))
    await pg.click('[data-act="restart"]'); await pg.evaluate('()=>{__game.score=1000}'); await pg.click('#bPause'); await pg.click('[data-act="menu"]')
    check('quitting mid-run also banks (+2 VP)', (await save(pg))['vp'] == 22)
    await pg.click('[data-act="kinds"]'); check('unlock button disabled without enough VP', await pg.evaluate("()=>document.querySelector('[data-act=\"buy:2\"]').disabled"))
    await pg.evaluate("()=>{const s=JSON.parse(localStorage.getItem('slidingcups.save'));s.vp=150;localStorage.setItem('slidingcups.save',JSON.stringify(s))}")
    await pg.reload(); await pg.wait_for_timeout(400); await enter(pg); await pg.click('[data-act="kinds"]'); await pg.click('[data-act="buy:2"]')
    s = await save(pg); check('unlock 3rd creature: -100 VP', s['vp'] == 50 and s['unlocked'] == [0, 1, 2], s)
    check('Capture Beasts is list only (no add/remove toggle)', not await pg.evaluate("()=>!!document.querySelector('[data-act^=\"kind:\"]')") and 'Tamed' in await pg.inner_text('#ov'))
    await pg.click('[data-act="menu"]'); await pg.click('[data-act="prep:classic"]'); await pg.click('[data-act="kind:2"]'); await pg.click('#ov [data-act="start"]')
    check('creatures chosen on the prep screen are used in the game', await pg.evaluate('()=>__game.kinds') == [0, 2])
    await pg.evaluate("()=>localStorage.setItem('slidingcups.save','{broken save')"); await pg.reload(); await pg.wait_for_timeout(400); await enter(pg)
    check('a corrupted save does not crash; back to a fresh player', await flow(pg) == 'menu')
    await c.close()

async def t_levels(b):
    print('Levels'); c, pg = await new_page(b, viewport={'width': 820, 'height': 1100}); await fresh(pg)
    await pg.click('[data-act="levels"]')
    nlv = await pg.evaluate('()=>SC.CONFIG.levels.length')
    check('chapters 1–4 listed (all levels); only level 1 open', nlv >= 29 and await pg.evaluate("()=>[...document.querySelectorAll('[data-act^=\"level:\"]')].map(e=>e.disabled).join()") == ','.join(['false'] + ['true'] * (nlv - 1)) and 'Chapter 2' in await pg.inner_text('#ov') and 'Chapter 3 · Gates of the Sun' in await pg.inner_text('#ov') and 'Chapter 4 · The Drowned Capital' in await pg.inner_text('#ov'))
    await pg.click('[data-act="level:0"]')
    check('first level of chapter 1 opens on the chapter opening card', await flow(pg) == 'story' and 'Old Elden lights one torch' in await pg.inner_text('#ov'))
    await pg.click('[data-act="storygo"]')
    check('opening card → briefing with Elden\'s line and the goal', await flow(pg) == 'brief' and 'Every king was once a pawn' in await pg.inner_text('#ov') and 'Make a Knight' in await pg.inner_text('#ov') and (await save(pg))['story'] == ['ch1.open'])
    await pg.click('[data-act="start"]'); await pg.wait_for_timeout(300)
    check('start → playing level 1 with its layout', await flow(pg) == 'playing' and await pg.evaluate("()=>[__game.level,__game.world.cups.length]") == [0, 2])
    check('coach: start hint and demo on level 1', await pg.evaluate("()=>__tutor.hint&&__tutor.hint.key") == 'first.a' and await pg.evaluate("()=>__tutor.demoOn"))
    await pg.click('#bPause'); check('pause shows the goal and progress', 'Make a Knight' in await pg.inner_text('#ov') and '0/1' in await pg.inner_text('#ov'))
    await pg.click('[data-act="resume"]')
    await pg.evaluate("()=>{__game.prog=1}"); await pg.wait_for_timeout(1300)
    s = await save(pg)
    check('clear → result with stars, first clear + star VP', await flow(pg) == 'result' and '★★★' in await pg.inner_text('#ov') and s['cleared'] == [0] and s['stars'][0] == 3 and s['vp'] == 20 + 20, s)
    check('chapter 1 recap: new skill + next level', 'New skill' in await pg.inner_text('#ov') and 'Next: The Line' in await pg.inner_text('#ov'))
    await pg.click('[data-act="next"]'); check('next → briefing of level 2', await flow(pg) == 'brief' and await pg.evaluate('()=>__game.level') == 1)
    await pg.click('[data-act="start"]'); await pg.wait_for_timeout(100); check('level 2 shows its own start hint', await pg.evaluate("()=>__tutor.hint&&__tutor.hint.key") == 'line.a')
    await pg.click('#bPause'); await pg.click('[data-act="restart"]'); check('restarting inside a level keeps the same level', await pg.evaluate('()=>__game.level') == 1)
    await pg.click('#bPause'); await pg.click('[data-act="levels"]'); await pg.click('[data-act="level:0"]')
    check('the opening card shows only once', await flow(pg) == 'brief'); await pg.click('[data-act="start"]')
    await pg.evaluate("()=>{__game.prog=1}"); await pg.wait_for_timeout(1300)
    check('replaying a cleared level gives no VP', (await save(pg))['vp'] == 40)
    await pg.evaluate("()=>{const s=JSON.parse(localStorage.getItem('slidingcups.save'));s.cleared=[0,1,2,3,4,5,6];localStorage.setItem('slidingcups.save',JSON.stringify(s))}")
    await pg.reload(); await pg.wait_for_timeout(400); await enter(pg); await pg.click('[data-act="levels"]'); await open_level(pg, 7); await pg.click('[data-act="start"]')
    await pg.evaluate("()=>{__game.prog=1}"); await pg.wait_for_timeout(1300)
    check('clearing the chapter 1 finale: result offers Continue (no Next yet)', await pg.evaluate("()=>!!document.querySelector('[data-act=storyclose]')&&!document.querySelector('[data-act=next]')"))
    await pg.click('[data-act="storyclose"]'); check('closing card of chapter 1', await flow(pg) == 'story' and 'The dragon on the wall' in await pg.inner_text('#ov'))
    await pg.click('[data-act="storygo"]'); check('…then chapter 2 opening card', await flow(pg) == 'story' and 'A white unicorn' in await pg.inner_text('#ov'))
    await pg.click('[data-act="storygo"]'); check('…then the briefing of level 9', await flow(pg) == 'brief' and await pg.evaluate('()=>__game.level') == 8 and sorted((await save(pg))['story']) == ['ch1.close', 'ch1.open', 'ch2.open'])
    await pg.click('[data-act="levels"]'); check('chapter list offers re-reading opening and closing cards', await pg.evaluate("()=>[...document.querySelectorAll('[data-act^=\"story:\"]')].map(e=>e.dataset.act).join()") == 'story:ch1.open,story:ch1.close,story:ch2.open')
    await pg.click('[data-act="story:ch1.close"]'); await pg.click('[data-act="storygo"]'); check('re-reading returns to the chapter list', await flow(pg) == 'levels')
    await c.close()

async def t_chapter3(b):
    print('Chapter 3: Gates of the Sun'); c, pg = await new_page(b, viewport={'width': 820, 'height': 1100}); await pg.goto(URL)
    sv = {'v': 8, 'cleared': list(range(16)), 'stars': [3] * 16, 'story': ['ch1.open', 'ch1.close', 'ch2.open', 'ch2.close'], 'unlocked': [0, 1], 'active': [0]}
    await pg.evaluate("s=>localStorage.setItem('slidingcups.save',JSON.stringify(s))", sv); await pg.reload(); await pg.wait_for_timeout(400); await enter(pg)
    await pg.click('[data-act="levels"]'); check('level 17 open after the basilisk, 18 locked', await pg.evaluate("()=>[16,17].map(i=>document.querySelector('[data-act=\"level:'+i+'\"]').disabled)") == [False, True])
    await pg.click('[data-act="level:16"]'); check('level 17 opens on the chapter 3 opening card', await flow(pg) == 'story' and 'A griffin finds you' in await pg.inner_text('#ov'))
    await pg.click('[data-act="storygo"]'); txt = await pg.inner_text('#ov')
    check('briefing: Night Dunes, Elden\'s line, goal and the sand rule', 'Night Dunes' in txt and 'Sand eats your strength' in txt and 'Make a Bishop' in txt and 'Sand:' in txt, txt)
    await pg.click('[data-act="start"]'); await pg.wait_for_timeout(300)
    cam = await pg.evaluate("()=>__fx.cameo&&{id:__fx.cameo.id,landed:__fx.cameo.landed,kind:__fx.cameo.kind}")
    check('griffin cameo: the first layout cup is carried in (not landed yet)', cam and not cam['landed'] and await pg.evaluate("id=>__game.world.cups.some(c=>c.id===id)", cam['id']))
    check('sand patches loaded and griffin sprites in use', await pg.evaluate("()=>__game.world.sand.length") == 1 and await pg.evaluate("()=>__sprites.imgs['griffin_t6']&&__sprites.imgs['griffin_t6'].ok"))
    await pg.wait_for_timeout(2300); check('…the cup lands and the cameo ends', await pg.evaluate("()=>__fx.cameo") is None)
    await pg.evaluate("()=>{__act('menu')}"); await pg.evaluate("()=>{SC.Game.startLevel(__game,20);__flow.state='brief';__act('start')}"); await pg.wait_for_timeout(200)
    await pg.evaluate("()=>{const g=__game;g.world.cups=g.world.cups.filter(c=>c.held);g.world.cups.push(SC.Physics.makeCup(g.world,5,2,300,300));g.shots=1;g.held.held=false;g.held.x=40;g.held.y=200;g.held=null;g.phase='flying';g.settleT=0}")
    await pg.wait_for_timeout(700); check('stingers: a cup is stung between shots (sound + mark)', await pg.evaluate("()=>__game.world.cups.some(c=>c.sting===3)") and (await pg.evaluate('()=>__sfx.stats')).get('wall', 0) >= 1)
    await pg.evaluate("()=>{__act('menu')}"); await pg.evaluate("()=>{SC.Game.startLevel(__game,23);__flow.state='brief';__act('start')}"); await pg.wait_for_timeout(200)
    check('boss: two guardian statues with full health; goal 0/2', await pg.evaluate("()=>__game.world.pillars.filter(p=>p.guard&&p.hp===p.max).length") == 2 and await pg.evaluate("()=>SC.Game.goalProgress(__game)") == {'have': 0, 'need': 2})
    await pg.evaluate("()=>{const g=__game,P=SC.Physics;g.world.cups=g.world.cups.filter(c=>c.held);for(const p of g.world.pillars)p.hp=1;for(const x of [150,450]){const a=P.makeCup(g.world,6,0,x-40,240),b=P.makeCup(g.world,6,0,x+40,240);a.vx=500;g.world.cups.push(a,b);}g.phase='flying'}")
    await pg.wait_for_timeout(1500); check('breaking both guardians clears the boss; result offers the closing card', await flow(pg) == 'result' and await pg.evaluate("()=>!!document.querySelector('[data-act=storyclose]')"))
    await pg.click('[data-act="storyclose"]'); check('chapter 3 closing card', await flow(pg) == 'story' and 'first sunrise in a year' in await pg.inner_text('#ov'))
    await pg.click('[data-act="storygo"]'); check('…then straight on to the chapter 4 opening card', await flow(pg) == 'story' and 'ch3.close' in (await save(pg))['story'] and 'Aurelia' in await pg.inner_text('#ov'))
    await c.close()

async def t_chapter4(b):
    print('Chapter 4: The Drowned Capital'); c, pg = await new_page(b, viewport={'width': 820, 'height': 1100}); await pg.goto(URL)
    sv = {'v': 9, 'cleared': list(range(24)), 'stars': [3] * 24, 'story': ['ch1.open', 'ch1.close', 'ch2.open', 'ch2.close', 'ch3.open', 'ch3.close'], 'unlocked': [0, 1], 'active': [0]}
    await pg.evaluate("s=>localStorage.setItem('slidingcups.save',JSON.stringify(s))", sv); await pg.reload(); await pg.wait_for_timeout(400); await enter(pg)
    await pg.click('[data-act="levels"]'); check('level 25 open after the twin guardians, 26 locked', await pg.evaluate("()=>[24,25].map(i=>document.querySelector('[data-act=\"level:'+i+'\"]').disabled)") == [False, True])
    check('chapter 4 header', 'Chapter 4 · The Drowned Capital' in await pg.inner_text('#ov'))
    await pg.click('[data-act="level:24"]'); txt = await pg.inner_text('#ov')
    check('level 25 opens on the chapter 4 opening card (STORY.md text)', await flow(pg) == 'story' and 'Under the black lake lies Aurelia' in txt and 'You must end each fight in a single stroke.' in txt, txt[:200])
    await pg.click('[data-act="storygo"]'); txt = await pg.inner_text('#ov')
    check('briefing: Lighthouse Rock, Elden\'s line, goal and the current rule', 'Lighthouse Rock' in txt and 'Her flame is fading.' in txt and 'Make a Bishop' in txt and 'Currents:' in txt, txt)
    await pg.click('[data-act="start"]'); await pg.wait_for_timeout(300)
    check('phoenix cameo: the phoenix lights the table', await pg.evaluate("()=>!!(__fx.cameo&&__fx.cameo.light&&__fx.cameo.kind===3)"))
    check('water bands loaded; phoenix sprites in use', await pg.evaluate("()=>__game.world.current.length") == 1 and await pg.evaluate("()=>__sprites.imgs['phoenix_t6']&&__sprites.imgs['phoenix_t6'].ok"))
    await pg.wait_for_timeout(2700); check('…the cameo ends', await pg.evaluate("()=>__fx.cameo") is None)
    drift = await pg.evaluate("()=>new Promise(r=>{const g=__game,c=SC.Physics.makeCup(g.world,3,0,300,560);c.vy=-500;g.world.cups.push(c);g.phase='flying';setTimeout(()=>r(c.x-300),900)})")
    check('a piece moving through the current is pushed sideways (to the right on level 25)', drift > 3, drift)
    await pg.evaluate("()=>{__act('menu')}"); await pg.evaluate("()=>{SC.Game.startLevel(__game,29);__flow.state='brief';__act('start')}"); await pg.wait_for_timeout(200)
    check('level 30: one hydra head with full health; goal 0/1', await pg.evaluate("()=>__game.world.pillars.filter(p=>p.head&&p.hp===p.max).length") == 1 and await pg.evaluate("()=>SC.Game.goalProgress(__game)") == {'have': 0, 'need': 1})
    await pg.evaluate("()=>{const g=__game,P=SC.Physics,h=g.world.pillars[0];g.world.cups=g.world.cups.filter(c=>c.held);h.hp=1;const a=P.makeCup(g.world,2,0,h.x-45,h.y+90),b=P.makeCup(g.world,2,0,h.x+45,h.y+90);a.vx=500;g.world.cups.push(a,b);g.phase='flying'}")
    await pg.wait_for_timeout(600); check('a plain merge cuts the head: a stump with a regrow countdown, not burned', await pg.evaluate("()=>{const h=__game.world.pillars[0];return [h.cut>0,!!h.burned,__game.prog]}") == [True, False, 0])
    await pg.evaluate("()=>{__act('menu')}"); await pg.evaluate("()=>{SC.Game.startLevel(__game,31);__flow.state='brief';__act('start')}"); await pg.wait_for_timeout(200)
    txt = await pg.evaluate("()=>SC.Game.goalProgress(__game)"); check('boss: three heads, goal 0/3', txt == {'have': 0, 'need': 3} and await pg.evaluate("()=>__game.world.pillars.filter(p=>p.head).length") == 3)
    await pg.evaluate("()=>{const g=__game;g.world.cups=g.world.cups.filter(c=>c.held);g.shots=3;g.held.held=false;g.held.x=40;g.held.y=200;g.held=null;g.phase='flying';g.settleT=0}")
    await pg.wait_for_timeout(700); check('rising water: after 3 shots the danger line climbs', await pg.evaluate("()=>__game.lineY") == 720 - 25)
    await pg.screenshot(path='/tmp/v/ch4_hydra.png')
    await pg.evaluate("()=>{const g=__game,P=SC.Physics;g.world.cups=g.world.cups.filter(c=>c.held);for(const h of g.world.pillars){h.hp=0;h.cut=2;const a=P.makeCup(g.world,2,0,h.x-45,h.y+95),b=P.makeCup(g.world,2,0,h.x+45,h.y+95),d=P.makeCup(g.world,2,0,h.x,h.y+133);a.vx=500;g.world.cups.push(a,b,d);}g.phase='flying'}")
    await pg.wait_for_timeout(1500); check('burning all three heads clears the boss; result offers the closing card', await flow(pg) == 'result' and await pg.evaluate("()=>!!document.querySelector('[data-act=storyclose]')"))
    await pg.click('[data-act="storyclose"]'); txt = await pg.inner_text('#ov'); check('chapter 4 closing card (STORY.md text)', await flow(pg) == 'story' and 'The Rebirth Feather,' in txt and 'Now we climb.' in txt, txt[:200])
    await pg.click('[data-act="storygo"]'); check('…then straight on to the finale opening card', await flow(pg) == 'story' and 'ch4.close' in (await save(pg))['story'] and 'The throne hall is cold.' in await pg.inner_text('#ov'))
    await c.close()

async def t_finale(b):
    print('Finale: The Grail Throne'); c, pg = await new_page(b, viewport={'width': 820, 'height': 1100}); await pg.goto(URL)
